create unique index if not exists uq_network_leaderboard_source on public.network_leaderboard_participation(leaderboard_key,actor_id,actor_type,source_event,source_id,period_start,period_end) where source_id is not null;

create or replace function public.record_network_leaderboard_participation(p_leaderboard_key text,p_actor_id uuid,p_actor_type text,p_metric_value numeric,p_source_event text,p_source_id uuid default null,p_period_start date default null,p_period_end date default null,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_id uuid;v_user uuid:=auth.uid();begin if v_user is null then raise exception 'Authentication required';end if;if not exists(select 1 from public.network_leaderboard_sources where leaderboard_key=p_leaderboard_key and active) then raise exception 'Unknown or inactive leaderboard';end if;if p_actor_type='user' then if p_actor_id<>v_user then raise exception 'actor identity mismatch';end if;elsif p_actor_type in ('business','fleet','enterprise') then if not exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=p_actor_id and bm.user_id=v_user and bm.role in ('owner','manager') and (p_actor_type='business' or lower(b.business_tier::text)=p_actor_type)) then raise exception 'actor access denied';end if;else raise exception 'invalid actor type';end if;insert into public.network_leaderboard_participation(leaderboard_key,actor_id,actor_type,metric_value,source_event,source_id,period_start,period_end,metadata) values(p_leaderboard_key,p_actor_id,p_actor_type,p_metric_value,p_source_event,p_source_id,p_period_start,p_period_end,coalesce(p_metadata,'{}'::jsonb)) on conflict do nothing returning id into v_id;if v_id is null then select id into v_id from public.network_leaderboard_participation where leaderboard_key=p_leaderboard_key and actor_id=p_actor_id and actor_type=p_actor_type and source_event=p_source_event and source_id=p_source_id and period_start is not distinct from p_period_start and period_end is not distinct from p_period_end order by id desc limit 1;end if;return v_id;end $$;

create or replace function public.record_geofence_event(p_geofence_id uuid,p_user_id uuid,p_location_id uuid,p_business_id uuid,p_event_type text,p_dwell_seconds integer default null,p_metadata jsonb default '{}'::jsonb,p_notification_id uuid default null,p_qr_code_id uuid default null,p_check_in_id uuid default null) returns uuid language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare v_id uuid;begin if auth.uid() is null then raise exception 'authentication required';end if;if p_user_id is distinct from auth.uid() then raise exception 'user identity mismatch';end if;if p_geofence_id is null or p_location_id is null then raise exception 'geofence and location required';end if;if not exists(select 1 from public.geofences g where g.id=p_geofence_id and g.location_id=p_location_id and (p_business_id is null or g.business_id=p_business_id)) then raise exception 'geofence scope mismatch';end if;insert into public.geofence_events(geofence_id,user_id,location_id,business_id,event_type,dwell_seconds,metadata,notification_id,qr_code_id,check_in_id) values(p_geofence_id,auth.uid(),p_location_id,p_business_id,p_event_type,p_dwell_seconds,coalesce(p_metadata,'{}'::jsonb),p_notification_id,p_qr_code_id,p_check_in_id) returning id into v_id;return v_id;end $$;

create or replace function public.refresh_contributor_milestones(p_user_id uuid) returns table(milestone_key text,achieved boolean,progress integer,target integer,points_awarded integer) language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare obs integer;checks integer;m text;target_value integer;reward integer;inserted boolean;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_user_id is distinct from auth.uid() then raise exception 'User identity mismatch';end if;select coalesce(observations_count,0),coalesce(verified_checkins_count,0) into obs,checks from contributor_reputation where user_id=auth.uid();for m,target_value,reward in values ('first_observation',1,10),('five_observations',5,25),('first_verified_checkin',1,15),('five_verified_checkins',5,50),('trusted_contributor',8,75),('verified_contributor',20,150) loop if m='first_observation' or m='five_observations' then progress:=least(obs,target_value);elsif m='first_verified_checkin' or m='five_verified_checkins' then progress:=least(checks,target_value);else progress:=least(obs,target_value);end if;if m='trusted_contributor' then achieved:=obs>=8 and checks>=4;elsif m='verified_contributor' then achieved:=obs>=20 and checks>=10;else achieved:=progress>=target_value;end if;inserted:=false;if achieved then insert into contributor_milestones(user_id,milestone_key,points_awarded) values(auth.uid(),m,reward) on conflict do nothing;inserted:=found;if inserted then insert into reward_transactions(user_id,points,reason,metadata) values(auth.uid(),reward,'contributor_milestone',jsonb_build_object('milestone',m));update profiles set points=coalesce(points,0)+reward where id=auth.uid();end if;end if;points_awarded:=case when inserted then reward else 0 end;milestone_key:=m;target:=target_value;return next;end loop;end $$;

create or replace function public.record_data_feature_event(p_event_type text,p_feature_code text default null,p_subject_type text default 'user',p_subject_id uuid default null,p_location_id uuid default null,p_business_id uuid default null,p_fleet_vehicle_id uuid default null,p_source_table text default null,p_source_id uuid default null,p_value_numeric numeric default null,p_value_text text default null,p_metadata jsonb default '{}'::jsonb) returns public.data_feature_events language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ declare uid uuid:=auth.uid();r public.data_feature_events;begin if uid is null then raise exception 'Authentication required';end if;if p_subject_type not in ('user','business','fleet_vehicle','location') then raise exception 'Invalid subject type';end if;if p_subject_type='user' and coalesce(p_subject_id,uid)<>uid then raise exception 'subject identity mismatch';end if;if p_location_id is not null and not exists(select 1 from public.locations where id=p_location_id and is_active=true) then raise exception 'location not found';end if;if p_business_id is not null and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=uid and bm.role in ('owner','manager','analyst')) then raise exception 'business access denied';end if;if p_fleet_vehicle_id is not null and not exists(select 1 from public.fleet_vehicles fv join public.business_members bm on bm.business_id=fv.business_id where fv.id=p_fleet_vehicle_id and bm.user_id=uid and bm.role in ('owner','manager','analyst')) then raise exception 'fleet vehicle access denied';end if;if p_subject_type='business' and (p_subject_id is null or not exists(select 1 from public.business_members bm where bm.business_id=p_subject_id and bm.user_id=uid and bm.role in ('owner','manager','analyst'))) then raise exception 'business subject access denied';end if;if p_subject_type='fleet_vehicle' and (p_subject_id is null or not exists(select 1 from public.fleet_vehicles fv join public.business_members bm on bm.business_id=fv.business_id where fv.id=p_subject_id and bm.user_id=uid and bm.role in ('owner','manager','analyst'))) then raise exception 'fleet subject access denied';end if;if p_subject_type='location' and p_subject_id is null then raise exception 'location subject required';end if;insert into public.data_feature_events(subject_type,subject_id,actor_user_id,business_id,location_id,fleet_vehicle_id,event_type,feature_code,source_table,source_id,value_numeric,value_text,metadata,occurred_at,event_validity,confidence,deduplication_key,rate_limit_context) values(p_subject_type,coalesce(p_subject_id,uid),uid,p_business_id,p_location_id,p_fleet_vehicle_id,p_event_type,p_feature_code,p_source_table,p_source_id,p_value_numeric,p_value_text,coalesce(p_metadata,'{}'::jsonb),now(),'valid',1,md5(concat_ws('|',uid::text,p_event_type,coalesce(p_source_id::text,''),coalesce(p_location_id::text,''),coalesce(p_value_text,''),date_trunc('minute',now())::text)),jsonb_build_object('minute',date_trunc('minute',now()))) returning * into r;return r;end $$;
